class PndMasterRunSim : public FairRunSim {
 public:
  /**
   * @brief Default constructor
   */
  PndMasterRunSim();

  /**
   * @brief Default destructor
   */
  virtual ~PndMasterRunSim();

  /**
   * @brief Initial setup
   * @details
   * This command set the source files, load the proper parameters,
   * and set the relevant flags. If something fails, it returns
   * a kFALSE value.
   */
  Bool_t Setup(TString outprefix = "");

  /**
   * @brief Final diagnostics
   * @details
   * It prints CPU time, memory usage, used parameters, and eventually
   * send the information to CDash
   */
  void Finish();

  /**
   * @brief It switches between different standard geometry volumes
   * @details
   * According to fOptions, it creates the standard geometry volumes for the
   * full setup, or dedicated geometries (such as day1)
   */
  void CreateGeometry();

  /**
   * @brief It creates all the standard geometry volumes
   * @details
   * It creates all the standard geometry volumes which have to be used in simulation.
   * All the MCPoint will be stored, expect for EMC.
   */
  void CreateGeometryDefault();

  /**
   * @brief It creates the standard geometry volumes for phase1 of the experiment
   * @details
   * It creates all the standard geometry volumes which have to be used in simulation,
   * with the setup for phase1 experiments. All the MCPoint will be stored, except for EMC
   */

  void CreateGeometryPhase1();

  /**
   * @brief It creates the standard geometry volumes for day1 phase
   * @details
   * It creates all the standard geometry volumes which have to be used in simulation,
   * with the setup for day1 experiments. All the MCPoint will be stored, except for EMC
   */

  void CreateGeometryDay1();

  /**
   * @brief Add simulation tasks
   * @details
   * It adds all the standard simulation tasks
   */
  void AddSimTasks();

  /**
   * @brief Set the event generator
   * @details
   * This call set the event generator according to the input name. If the input name
   * contains "dpm" it uses dpm, if it contains "ftf" then ftf, if ".dec" it runs evtgen
   * using the input name as namefile of the .dec file. If the input name contains
   * "box" the macro breaks, since in that case the SetGenerator(PndBoxGenerator *boxGen)
   * function must be used.
   */
  void SetGenerator();

  /**
   * @brief Add a generator to existing setup
   * @details
   * Adds a generator to the existing one. ALL generators will be active
   * and produce their particle content in each event simultaneously.
   */
  void AddGenerator(FairGenerator *aGen);

  /**
   * @brief Set the event generator
   * @details
   * The user should create a FairGenerator derived object with all the settings,
   * and pass it as argument to the function.
   */
  void SetGenerator(FairGenerator *aGen);

  /**
   * @brief Set the DPM flag
   * @param Mode = 0. - DPM - No elastic scattering, only inelastic
   * @param Mode = 1. - DPM - Elastic and inelastic interactions (default)
   * @param Mode = 2. - DPM - Only elastic scattering, no inelastic one
   */
  void SetDpmFlag(Int_t Mode) { fDpmFlag = Mode; };

  /**
   * @brief Set the FTF noelastic flag
   * @param Mode = 0. - FTF - Elastic and inelastic interactions (default)
   * @param Mode = 1. - FTF - No elastic scattering, only inelastic
   */
  void SetFtfFlag(Int_t Mode) { fFtfFlag = Mode; };

class PndMasterRunAna : public FairRunAna {
 public:
  /**
   * @brief Default constructor
   */
  PndMasterRunAna();

  /**
   * @brief Default destructor
   */
  virtual ~PndMasterRunAna();

  /**
   * @brief Initial setup
   * @details
   * This command set the source files, load the proper parameters,
   * and set the relevant flags. If something fails, it returns
   * a kFALSE value.
   */
  Bool_t Setup(TString outprefix = "");

  /**
   * @brief Final diagnostics
   * @details
   * It prints CPU time, memory usage, used parameters, and eventually
   * send the information to CDash
   */
  void Finish();

  /**
   * @brief Add digitization and local reconstruction tasks
   * @details
   * @param pers Persistency of the TCAs, used only to switch OFF
   * It calls PndMasterDigiTask, adding all the standard digitization tasks
   */
  void AddDigiTasks(Bool_t pers = kTRUE);

  /**
   * @brief Add digitization tasks without reconstruction
   * @details
   * @param pers Persistency of the TCAs, used only to switch OFF
   * It calls PndMasterDigiTask, adding all the standard digitization tasks
   */
  void AddDigiOnlyTasks(Bool_t pers = kTRUE);

  /**
   * @brief Add reconstruction tasks
   * @details
   * @param pers Persistency of the TCAs, used only to switch OFF
   * It calls PndMasterRecoTask, adding all the standard reconstruction tasks
   */
  void AddRecoTasks(Bool_t pers = kTRUE);

  /**
   * @brief Add local reconstruction tasks
   * @details
   * @param pers Persistency of the TCAs, used only to switch OFF
   * It calls PndMasterLocalRecoTask, adding all the standard reconstruction tasks
   */
  void AddLocalRecoTasks(Bool_t pers = kTRUE);

  /**
   * @brief Add ideal pattern reconstruction tasks
   * @details
   * @param pers Persistency of the TCAs, used only to switch OFF
   * It calls PndMasterRecoTask, adding all the standard reconstruction tasks
   */
  void AddRecoIdealTasks(Bool_t pers = kTRUE);

  /**
   * @brief Add pid tasks
   * @details
   * @param pers Persistency of the TCAs, used only to switch OFF
   * It calls PndMasterPidTask, adding all the standard pid tasks
   */
  void AddPidTasks(Bool_t pers = kTRUE);

  /**
   * @brief Input of the macro
   */
  void SetInput(TString par) { fInput = par; }

  /**
   * @brief Tag of the output file of the macro
   */
  void SetOutput(TString par) { fOutFile = par; }

  /**
   * @brief Setter of the parameter root file
   */
  void SetParamRootFile(TString par) { fParamRootFile = par; }

  /**
   * @brief Setter of the parameter ascii file
   */
  void SetParamAsciiFile(TString par) { fParamAsciiFile = par; }

  /**
   * @brief Setter of friend root files
   */
  void AddFriend(TString par)
  {
    if (par != "")
      fFriendFiles.push_back(par);
  }

  /**
   * @brief Setter of the reconstruction options
   * @details
   * @param par = ""     -> default settings
   * @param par = "day1" -> Setup for day1 experimentent, no GEM
   * @param par = "day1+GEM" -> Setup for day1 experimentent, 3 GEM planes
   */
  void SetOptions(TString par)
  {
    fOptions = par;
    fOptions.ToLower();
  }
  TString GetOptions() { return fOptions; }

  void PrintListOfTasks(TList *list, TString prefix = " - ");
  void PrintListOfTasks() { PrintListOfTasks(GetMainTask()->GetListOfTasks()); }

// Simulation Macro
// based on runMvdSim.C by Ralf Kliemt

// Macro to simulate the MVD in pandaroot
// Updated 30.11.2009
// Ralf Kliemt
runSimPions(Int_t nPions = 1, Int_t nEvents = 500)
{
  TStopwatch timer;
  timer.Start();
  gDebug = 0;
  int verboseLevel = 0;

  // FileNames
  TString simOutput = "Sim_Dpm_500.root";
  TString parOutput = "Sim_Dpm_500_params.root";

  // Load basic libraries
  gROOT->Macro("$VMCWORKDIR/gconfig/rootlogon.C");
  FairRunSim *fRun = new FairRunSim();

  // set the MC version used
  // ------------------------

  fRun->SetName("TGeant3");
  // fRun->SetName("TGeant4");
  // Choose the Geant Navigation System

  fRun->SetOutputFile(simOutput);

  // Fill the Parameter containers for this run
  //-------------------------------------------
  FairRuntimeDb *rtdb = fRun->GetRuntimeDb();
  Bool_t kParameterMerged = kTRUE;
  FairParRootFileIo *output = new FairParRootFileIo(kParameterMerged);
  output->open(parOutput.Data(), "RECREATE");
  rtdb->setOutput(output);

  // Set Material file Name
  //-----------------------
  fRun->SetMaterials("media_pnd.geo");

  // Create and add detectors
  //-------------------------

  FairModule *Cave = new PndCave("CAVE");
  Cave->SetGeometryFileName("pndcave.geo");
  fRun->AddModule(Cave);
  FairModule *Magnet = new PndMagnet("MAGNET");
  Magnet->SetGeometryFileName("magnet.geo");
  fRun->AddModule(Magnet);
  FairModule *Pipe = new PndPipe("PIPE");
  // fRun->AddModule(Pipe);
  //-------------------------  STT       -----------------
  FairDetector *Stt = new PndStt("STT", kTRUE);
  Stt->SetGeometryFileName("straws_skewed_blocks_35cm_pipe.geo");
  fRun->AddModule(Stt);

  FairDetector *Mvd = new PndMvdDetector("MVD", kTRUE);
  Mvd->SetGeometryFileName("Mvd-2.1_FullVersion.root"); // only sensors, update follows
  Mvd->SetVerboseLevel(verboseLevel);
  fRun->AddModule(Mvd);
  //-------------------------  GEM       -----------------
  FairDetector *Gem = new PndGemDetector("GEM", kTRUE);
  Gem->SetGeometryFileName("gem_3Stations.root");
  fRun->AddModule(Gem);
  //-------------------------  EMC       -----------------
  PndEmc *Emc = new PndEmc("EMC", kTRUE);
  Emc->SetGeometryVersion(2);
  Emc->SetStorageOfData(kFALSE);
  fRun->AddModule(Emc);
  //-------------------------  DRC       -----------------
  PndDrc *Drc = new PndDrc("DIRC", kTRUE);
  Drc->SetGeometryFileName("dirc_l0_p0.root");
  Drc->SetRunCherenkov(kFALSE);
  fRun->AddModule(Drc);
  //-------------------------  DISC      -----------------
  PndDsk *Dsk = new PndDsk("DSK", kTRUE);
  Dsk->SetGeometryFileName("dsk.root");
  Dsk->SetStoreCerenkovs(kFALSE);
  Dsk->SetStoreTrackPoints(kFALSE);
  fRun->AddModule(Dsk);
  //-------------------------  MDT       -----------------
  PndMdt *Muo = new PndMdt("MDT", kTRUE);
  Muo->SetBarrel("fast");
  Muo->SetEndcap("fast");
  Muo->SetMuonFilter("fast");
  Muo->SetMdtMagnet(kTRUE);
  Muo->SetMdtMFIron(kTRUE);
  //  fRun->AddModule(Muo);
  //-------------------------  FTS       -----------------
  FairDetector *Fts = new PndFts("FTS", kTRUE);
  Fts->SetGeometryFileName("fts.geo");
  fRun->AddModule(Fts);

  FairPrimaryGenerator *primGen = new FairPrimaryGenerator();
  fRun->SetGenerator(primGen);

  // Particle Generator (pdgid,mult, px,py,pz, vx,vy,vz)
  // single pions for testing
  //      FairParticleGenerator* partGenX   = new FairParticleGenerator(211,1, 1.,0.,0., 0.,0.,0.);
  //      FairParticleGenerator* partGenY   = new FairParticleGenerator(211,1, 0.,1.,0., 0.,0.,0.);
  //      FairParticleGenerator* partGenZ   = new FairParticleGenerator(211,1, 0.,0.1,1., 0.,0.,0.);
  //      FairParticleGenerator* partGenXYZ = new FairParticleGenerator(211,1, 1.,1.,5., 0.,0.,0.);
  //      primGen->AddGenerator(partGenX);
  //      primGen->AddGenerator(partGenY);
  //      primGen->AddGenerator(partGenZ);
  //      primGen->AddGenerator(partGenXYZ);

  // Ion Generator
  //    FairIonGenerator *fIongen= new FairIonGenerator(79, 197,79,1, 0.,0., 25, 0.,0.,-1.);
  //    primGen->AddGenerator(fIongen);

  // Box Generator
  // Pions
  FairBoxGenerator *fBox = new FairBoxGenerator(211, nPions);
  fBox->SetPRange(0.2, 2.5);
  fBox->SetThetaRange(40, 120);
  fBox->SetPhiRange(0., 360.);
  fBox->SetCosTheta();
  primGen->AddGenerator(fBox);

  // EvtGen Generator
  //    FairEvtGenGenerator* evtGen = new
  //      FairEvtGenGenerator("/home/ralfk/Pandaroot/pandaroot/macro/mvd/output.evt");
  //    primGen->AddGenerator(evtGen);

  // Urqmd  Generator
  //    FairUrqmdGenerator* urqmdGen = new FairUrqmdGenerator("../../input/00-03fm.100ev.f14");
  //    primGen->AddGenerator(urqmdGen);

  // DPM Generator
  // PndDpmGenerator* dpmGen = new PndDpmGenerator("/home/kph/stockman/fairroot/cbmroot/pandaroot/pgenerators/DpmEvtGen/Background-micro.root");
  // primGen->AddGenerator(dpmGen);

  // Field Map Definition
  // --------------------
  // 1- Reading the new field map in the old format

  // PndDpmDirect *dpmGen = new PndDpmDirect(15,1, gRandom->GetSeed());
  // primGen->AddGenerator(dpmGen);

  fRun->SetBeamMom(15);
  //---------------------Create and Set the Field(s)----------
  PndMultiField *fField = new PndMultiField("FULL");
  fRun->SetField(fField);

  fRun->SetStoreTraj(kTRUE);       // toggle this for use with EVE
  fRun->SetRadLenRegister(kFALSE); // toggle for material budget study

  fRun->Init();

  // Set cuts for storing the trajectpries
  //   FairTrajFilter* trajFilter = FairTrajFilter::Instance();
  //     trajFilter->SetStepSizeCut(0.01); // 1 cm
  //     trajFilter->SetVertexCut(-200., -200., -200, 200., 200., 200.);
  //     trajFilter->SetMomentumCutP(10e-3); // p_lab > 10 MeV
  //     trajFilter->SetEnergyCut(0., 1.02); // 0 < Etot < 1.04 GeV
  //     trajFilter->SetStorePrimaries(kTRUE);
  //     trajFilter->SetStoreSecondaries(kTRUE);

  // Transport nEvents
  // -----------------

  fRun->Run(nEvents);

  rtdb->saveOutput();
  rtdb->print();

  timer.Stop();
  Double_t rtime = timer.RealTime();
  Double_t ctime = timer.CpuTime();
  printf("RealTime=%f seconds, CpuTime=%f seconds\n", rtime, ctime);
}

