void PndMasterRunSim::CreateGeometry()
{
  if (fOptions.Contains("phase1"))
    CreateGeometryPhase1();
  else if (fOptions.Contains("day1"))
    CreateGeometryDay1();
  else
    CreateGeometryDefault();
}

